SELECT ap.*, a.asset_code FROM lab_equipment_apply ap LEFT JOIN lab_equipment_asset a ON ap.asset_id = a.id
WHERE 1=1
AND ap.equipment_id = #{equipmentId}
AND ap.user_id = #{userId}
AND ap.apply_time >= #{startTime}
AND ap.apply_time <= #{endTime}

