UPDATE lab_equipment_apply
approval_status = #{approve_status}, approval_time = #{approve_time}, approval_user_id = #{approve_user_id}, approval_user_name = #{approval_user_name}, status_text = #{status_text}, return_time = #{return_time}, equipment_status = #{equipment_status}, remarks = #{remarks}, return_status = #{return_status}, return_apply_time = #{return_apply_time,jdbcType=TIMESTAMP}, asset_id = #{asset_id}, status = #{status}, original_status = #{original_status},
